import {readFileSync, writeFileSync} from "node:fs";
import {fileURLToPath} from "node:url";
import {dirname, join} from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const fonts = [
  ["familjenGroteskDataUrl", "familjen-grotesk.woff2"],
  ["ibmPlexSansDataUrl", "ibm-plex-sans.woff2"],
  ["ibmPlexMonoDataUrl", "ibm-plex-mono-500.woff2"],
];

const source = [
  "// Generated by scripts/generate-font-data.mjs. Do not edit by hand.",
  ...fonts.map(([name, file]) => {
    const encoded = readFileSync(join(root, "public", "assets", file)).toString("base64");
    return `export const ${name} = "data:font/woff2;base64,${encoded}";`;
  }),
  "",
].join("\n");

writeFileSync(join(root, "src", "font-data.generated.ts"), source);
